import { createVisualizer } from "./visualizer.js";
import { setupControls } from "./controls.js";

const visualizer = createVisualizer(document.getElementById("scene-container"));
const engineDot = document.getElementById("engine-dot");
const engineStatus = document.getElementById("engine-status");

let cEngine = null;
try {
  // This file is generated by Emscripten after you compile coordinates.c.
  const { default: createModule } = await import("../wasm/coordinates.js");
  cEngine = await createModule();
  engineStatus.textContent = "C / WebAssembly active";
  engineDot.style.background = "#55dfb0";
  engineDot.style.boxShadow = "0 0 12px #55dfb088";
} catch (error) {
  engineStatus.textContent = "JavaScript fallback";
  engineDot.style.background = "#f2bd61";
  engineDot.style.boxShadow = "0 0 12px #f2bd6188";
  console.info("WebAssembly module not found yet. Compile coordinates.c to activate the C engine.", error);
}

function calculate(x, y, z) {
  if (cEngine) {
    return {
      r: cEngine._get_r(x, y),
      theta: cEngine._get_theta_deg(x, y),
      rho: cEngine._get_rho(x, y, z),
      phi: cEngine._get_phi_deg(x, y, z)
    };
  }

  // Temporary fallback so the website works before the C module is compiled.
  const r = Math.hypot(x, y);
  const rho = Math.hypot(x, y, z);
  let theta = Math.atan2(y, x) * 180 / Math.PI;
  if (theta < 0) theta += 360;
  const phi = rho === 0 ? 0 : Math.acos(Math.max(-1, Math.min(1, z / rho))) * 180 / Math.PI;
  return { r, theta, rho, phi };
}

setupControls({ visualizer, calculate });
